package id.imperial.shop; import org.bukkit.command.*;import org.bukkit.entity.Player;public final class SellAllCommand implements CommandExecutor{final ShopService s;SellAllCommand(ShopService s){this.s=s;}public boolean onCommand(CommandSender c,Command cmd,String l,String[] a){if(!(c instanceof Player p)){c.sendMessage("Player only.");return true;}double t=s.sellContents(p);if(t>0){s.economy.depositPlayer(p,t);p.sendMessage("§aBerhasil menjual inventory: §f"+s.money(t));}else p.sendMessage("§cTidak ada item yang dapat dijual.");return true;}}